1	import React, { useEffect, useState } from 'react';
2	
3	// A project's task checklist, rendered inside the projects feature when a project is opened. Lists
4	// the project's tasks and lets the owner tick each one off (OPEN <-> DONE). Owns its own state and
5	// data loading (no global store); composed, not branched.
6	type Task = { id: number; projectId: number; title: string; done: boolean };
7	
8	type Filter = 'ALL' | 'OPEN' | 'DONE';
9	
10	export function ProjectTasks({ projectId }: { projectId: number }) {
11	  const [tasks, setTasks] = useState<Task[]>([]);
12	  const [filter, setFilter] = useState<Filter>('ALL');
13	
14	  async function load(status: Filter = filter) {
15	    const res = await fetch(`/api/projects/${projectId}/tasks?status=${status}`);
16	    setTasks(await res.json());
17	  }
18	
19	  useEffect(() => {
20	    void load();
21	  }, [projectId]);
22	
23	  async function onFilter(status: Filter) {
24	    setFilter(status);
25	    await load(status);
26	  }
27	
28	  async function toggle(taskId: number) {
29	    const res = await fetch(`/api/tasks/${taskId}/toggle`, { method: 'POST' });
30	    if (!res.ok) {
31	      return;
32	    }
33	    await load();
34	  }
35	
36	  return (
37	    <section data-testid="project-tasks">
38	      <h2>Tasks</h2>
39	
40	      <select
41	        data-testid="task-filter"
42	        value={filter}
43	        onChange={(e) => void onFilter(e.target.value as Filter)}
44	      >
45	        <option value="ALL">All</option>
46	        <option value="OPEN">Open</option>
47	        <option value="DONE">Done</option>
48	      </select>
49	
50	      <table data-testid="project-tasks-table">
51	        <thead>
52	          <tr>
53	            <th>Task</th>
54	            <th>Status</th>
55	            <th></th>
56	          </tr>
57	        </thead>
58	        <tbody>
59	          {tasks.map((t) => (
60	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
61	              <td data-testid="task-title">{t.title}</td>
62	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
63	              <td>
64	                <button
65	                  type="button"
66	                  data-testid={`task-toggle-${t.id}`}
